  'متأكد إني أبي أمسح مخزون: {placeName}': { en: 'I am sure I want to clear the stock of: {placeName}', ne: 'म यसको स्टक खाली गर्न निश्चित छु: {placeName}', hi: 'मुझे यक़ीन है कि मैं इसका स्टॉक साफ़ करना चाहता हूँ: {placeName}' },
