  'ما سجلتش {n} عشان اترفعوا قبل كده: {v}': { en: 'Did not save {n} because they were uploaded before: {v}', ne: '{n} सेभ गरिएन किनभने पहिले अपलोड भइसकेको थियो: {v}', hi: '{n} सेव नहीं किए क्योंकि पहले अपलोड हो चुके थे: {v}' },
