  'كل اسم بيظهر مرة واحدة ومعاه كمية كل يوم والإجمالي. بتربطه مرة، وكل يوم بيتسجل بتاريخه.': { en: 'Each name appears once with its quantity for each day and the total. Link it once and each day is saved on its own date.', ne: 'हरेक नाम एक पटक, हरेक दिनको मात्रा र जम्मासहित देखिन्छ। एक पटक जोड्नुहोस्, हरेक दिन आफ्नै मितिमा सेभ हुन्छ।', hi: 'हर नाम एक बार दिखता है, हर दिन की मात्रा और कुल के साथ। एक बार जोड़ें, हर दिन अपनी तारीख पर सेव होगा।' },
  'محتاج مراجعة ({need})': { en: 'Needs review ({need})', ne: 'जाँच चाहिन्छ ({need})', hi: 'जाँच चाहिए ({need})' },
